<?php
require __DIR__.'/includes/bootstrap.php';require_login();$sid=store_id();$dateFrom=$_GET['from']??date('Y-m-01');$dateTo=$_GET['to']??date('Y-m-d');$validDate=fn($x)=>is_string($x)&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$x);if(!$validDate($dateFrom))$dateFrom=date('Y-m-01');if(!$validDate($dateTo))$dateTo=date('Y-m-d');
$st=$pdo->prepare('SELECT s.*,u.name cashier,(SELECT COUNT(*) FROM sale_items i WHERE i.store_id=s.store_id AND i.sale_id=s.id) line_count FROM sales s JOIN users u ON u.store_id=s.store_id AND u.id=s.user_id WHERE s.store_id=? AND DATE(s.created_at) BETWEEN ? AND ? ORDER BY s.created_at DESC LIMIT 250');$st->execute([$sid,$dateFrom,$dateTo]);$sales=$st->fetchAll();$detail=null;if(isset($_GET['id'])){$q=$pdo->prepare('SELECT s.*,u.name cashier FROM sales s JOIN users u ON u.store_id=s.store_id AND u.id=s.user_id WHERE s.store_id=? AND s.id=?');$q->execute([$sid,(int)$_GET['id']]);$detail=$q->fetch();if($detail){$q=$pdo->prepare('SELECT product_name,quantity,unit_price,line_total FROM sale_items WHERE store_id=? AND sale_id=? ORDER BY id');$q->execute([$sid,$detail['id']]);$detail['items']=$q->fetchAll();}}
$sort = (string)($_GET['sort'] ?? 'created_at');
$dir = strtoupper((string)($_GET['dir'] ?? 'DESC'));
$allowedSorts = ['id' => 's.id', 'created_at' => 's.created_at', 'cashier' => 'u.name', 'total' => 's.total', 'payment_method' => 's.payment_method'];
if (!isset($allowedSorts[$sort]) || !in_array($dir, ['ASC', 'DESC'], true)) { $sort = 'created_at'; $dir = 'DESC'; }
$st=$pdo->prepare('SELECT s.*,u.name cashier,(SELECT COUNT(*) FROM sale_items i WHERE i.store_id=s.store_id AND i.sale_id=s.id) line_count FROM sales s JOIN users u ON u.store_id=s.store_id AND u.id=s.user_id WHERE s.store_id=? AND DATE(s.created_at) BETWEEN ? AND ? ORDER BY ' . $allowedSorts[$sort] . ' ' . $dir . ' LIMIT 250');$st->execute([$sid,$dateFrom,$dateTo]);$sales=$st->fetchAll();
require __DIR__.'/includes/layout.php';page_header('Sales','sales');
$sortLink = function(string $field, string $label) use ($dateFrom, $dateTo, $sort, $dir) { $nextDir = ($sort === $field && $dir === 'ASC') ? 'DESC' : 'ASC'; return 'sales.php?from=' . urlencode($dateFrom) . '&to=' . urlencode($dateTo) . '&sort=' . urlencode($field) . '&dir=' . urlencode($nextDir); };
?><div class="page-head"><div><div class="eyebrow">Transactions</div><h1>Sales history</h1><p class="subtitle">Completed sales for your store.</p></div></div><section class="panel"><form class="filter-form" method="get"><div class="field"><label>From</label><input type="date" name="from" value="<?= e($dateFrom) ?>"></div><div class="field"><label>To</label><input type="date" name="to" value="<?= e($dateTo) ?>"></div><input type="hidden" name="sort" value="<?= e($sort) ?>"><input type="hidden" name="dir" value="<?= e($dir) ?>"><button class="btn btn-light">Filter</button></form><div class="table-wrap" style="margin-top:18px"><table><thead><tr><th><a class="sort-link" href="<?= $sortLink('id', 'Sale') ?>">Sale <?= ($sort === 'id' ? ($dir === 'ASC' ? '↑' : '↓') : '') ?></a></th><th><a class="sort-link" href="<?= $sortLink('created_at', 'Date & time') ?>">Date & time <?= ($sort === 'created_at' ? ($dir === 'ASC' ? '↑' : '↓') : '') ?></a></th><th><a class="sort-link" href="<?= $sortLink('cashier', 'Cashier') ?>">Cashier <?= ($sort === 'cashier' ? ($dir === 'ASC' ? '↑' : '↓') : '') ?></a></th><th>Items</th><th><a class="sort-link" href="<?= $sortLink('payment_method', 'Payment') ?>">Payment <?= ($sort === 'payment_method' ? ($dir === 'ASC' ? '↑' : '↓') : '') ?></a></th><th><a class="sort-link" href="<?= $sortLink('total', 'Total') ?>">Total <?= ($sort === 'total' ? ($dir === 'ASC' ? '↑' : '↓') : '') ?></a></th><th></th></tr></thead><tbody><?php if(!$sales): ?><tr><td class="empty" colspan="7">No transactions for those dates.</td></tr><?php endif;foreach($sales as $s): ?><tr><td class="product-cell">#<?= (int)$s['id'] ?></td><td><?= e(date('M j, Y · g:i A',strtotime($s['created_at']))) ?></td><td><?= e($s['cashier']) ?></td><td><?= (int)$s['line_count'] ?> lines</td><td><span class="badge"><?= e(ucfirst($s['payment_method'])) ?></span></td><td class="product-cell"><?= money($s['total']) ?></td><td><a class="text-link" href="sales.php?from=<?= e($dateFrom) ?>&amp;to=<?= e($dateTo) ?>&amp;id=<?= (int)$s['id'] ?>">View</a></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php if($detail): ?><div class="modal-backdrop show" id="receiptModal"><section class="modal"><div class="modal-title"><h2>Sale #<?= (int)$detail['id'] ?></h2><a class="icon-button" href="sales.php?from=<?= e($dateFrom) ?>&amp;to=<?= e($dateTo) ?>">×</a></div><p class="small-muted"><?= e(date('M j, Y · g:i A',strtotime($detail['created_at']))) ?> · <?= e($detail['cashier']) ?></p><div class="table-wrap"><table><thead><tr><th>Item</th><th>Qty</th><th>Price</th><th>Total</th></tr></thead><tbody><?php foreach($detail['items'] as $it): ?><tr><td><?= e($it['product_name']) ?></td><td><?= (int)$it['quantity'] ?></td><td><?= money($it['unit_price']) ?></td><td><?= money($it['line_total']) ?></td></tr><?php endforeach; ?></tbody></table></div><div class="total-line grand-total"><span>Total</span><strong><?= money($detail['total']) ?></strong></div><div class="total-line"><span>Payment</span><span><?= e(ucfirst($detail['payment_method'])) ?></span></div><?php if($detail['payment_method']==='cash'): ?><div class="total-line"><span>Cash received / change</span><span><?= money($detail['cash_received']) ?> / <?= money($detail['change_due']) ?></span></div><?php endif; ?><button class="btn btn-primary" onclick="window.print()">Print receipt</button></section></div><?php endif; ?>
<?php page_footer(); ?>
